'use strict';
// Presentation of an allowlisted, frozen readiness snapshot; no database calls.
const comparisonVariantNames={q20_equal:'상위 20% · 동일가중',q10_equal:'상위 10% · 동일가중',q20_sqrt_cap:'상위 20% · √시총 가중',q10_sqrt_cap:'상위 10% · √시총 가중'};
function comparisonBanner(){return comparison?`<div class="notice blue">이 상세 화면은 <strong>과거 동결 연구</strong>입니다. 현재 일별 승인 버전의 성과 재검증은 아직 완료되지 않았습니다. <a class="text-button" href="#comparison" data-close-link>새 비교 준비 상태 ↗</a></div>`:'';}
function comparisonFactors(query=''){
 const rows=comparison.factors.filter(f=>(title(f.name)+' '+f.name).toLowerCase().includes(query.toLowerCase()));
 return `<div class="table-caption"><strong>${rows.length}개 현재 승인 버전</strong><span>이름순 · 과거 발견일을 새 정의의 발견일로 사용하지 않음</span></div><div class="table-wrap"><table><thead><tr><th>팩터</th><th>현재 버전</th><th>점수 방향</th><th>과거 정의와 비교</th><th>새 월초 실행 성과</th></tr></thead><tbody>${rows.map(f=>`<tr><td><strong>${esc(title(f.name))}</strong><code>${esc(f.name)}</code></td><td>v${f.version}<small class="muted block">일별 계산 · 월별 매매</small></td><td>${f.predicted_sign===-1?'원시 값이 낮을수록 선호':'원시 값이 높을수록 선호'}</td><td>${badge(f.historical_binding==='CHANGED'?'정의 변경':f.historical_binding==='UNKNOWN'?'과거 해시 미확인':'정의 일치',f.historical_binding==='MATCH'?'blue':'amber')}<details class="source"><summary>정의 식별자</summary><p>현재: <code>${esc(f.definition_hash)}</code></p><p>과거: <code>${esc(f.historical_definition_hash||'없음')}</code></p>${f.lookback_translation?'<p>월 룩백을 21 KRX 거래일 단위로 번역한 일별 정의입니다.</p>':''}</details></td><td><span class="muted">미산출</span><small class="muted block">0%가 아니라 입력 준비 중</small></td></tr>`).join('')||'<tr><td colspan="5">검색 결과가 없습니다.</td></tr>'}</tbody></table></div>`;
}
function comparisonPage(){
 if(!comparison)return head('MONTHLY IMPLEMENTATION','비교 상태를 불러오지 못했습니다.','현재 버전·성과를 추정하지 않습니다. 새로고침 후 다시 확인해 주세요.');
 const c=comparison;
 return head('MONTHLY IMPLEMENTATION','월말에 판단하고,<br>월초에 매매한다.','현재 승인 버전으로 새로 고정한 개발용 비교입니다. 계획 등록과 성과 계산 완료는 다릅니다.')+
 notice(`<strong>계획 등록 완료 · 실제 성과는 아직 미산출.</strong> ${date(c.as_of)} DB에서 확인한 ${c.factor_count}개를 빠짐없이 고정했습니다. 시가 기준 총수익 등 실행 입력이 남아 있어 ${c.completed_comparisons}/${c.planned_comparisons}개 비교가 완료됐습니다. 기존 IC·OOS·교훈은 보존합니다.`)+
 stats([['현재 승인 팩터',c.factor_count,'모두 일별 계산 정의 · 자동 갱신 아님'],['고정 비교 방식',c.variants.length,'기준선 1 + 대안 3 · 자동 우승자 선택 없음'],['성과 계산 완료',`${c.completed_comparisons} / ${c.planned_comparisons}`,'가상 테스트를 시장 성과로 표시하지 않음'],['판단 기간',`${c.decision_start}–${c.decision_end}`,'수익 지원: 2026년 7월까지 · 독립 OOS 아님']])+
 window.MonthlyReadiness.render(c,()=>{if(location.hash.split('?')[0]==='#comparison')render();})+
 section('SIGNAL → TRADE → RETURN','계산 주기와 매매 주기를 구분합니다')+
 `<div class="three-grid"><article class="panel"><span class="step">01 / 월말 정보 마감</span><h3>일별 점수 중 월말 값을 선택</h3><p>한국시간 달력 월말 23:59:59까지 가용한 점수·종목군·시가총액만 사용합니다. Gold 값은 이미 방향이 적용돼 있어 부호를 다시 곱하지 않습니다.</p></article><article class="panel"><span class="step">02 / 다음 달 첫 거래일</span><h3>월초 시가에 비중 조정</h3><p>휴일과 특별 개장시간을 반영한 첫 정규 세션이 기준입니다. 월말 종가에 미리 매수한 것으로 처리하지 않습니다.</p></article><article class="panel"><span class="step">03 / 그다음 달 첫 거래일</span><h3>배당·비용을 포함해 비교</h3><p>시가→시가 보유수익을 계산하고, 바뀐 보유 비중에서 거래비용을 차감합니다. 실제 주문이나 체결 인증은 아닙니다.</p></article></div>`+
 section('FOUR FIXED RULES','20% 기준선을 두고, 10%와 가중법을 함께 비교')+
 `<div class="comparison-grid">${c.variants.map(v=>`<article class="panel"><span class="eyebrow">${v.baseline?'기준선':'비교안'}</span><h3>${esc(comparisonVariantNames[v.variant_id])}</h3><p>${v.weighting==='equal'?'선정한 각 종목에 같은 비중을 줍니다.':'시가총액의 제곱근에 비례해 비중을 줍니다. 단순 시총가중보다 대형주 쏠림을 완화하는 방식입니다.'}</p>${badge('성과 미산출','amber')}</article>`).join('')}</div><p class="chart-note">각 팩터를 단독 사용합니다. 같은 적격 종목군에서 floor(종목 수 × 비율), 최소 1개를 선택합니다. 과거 결과에 맞춰 비율·방향을 바꾸거나 팩터를 합성하지 않습니다.</p>`+
 section('REGISTERED INPUT STATUS','등록 당시 입력 인증 상태')+
 `<div class="two-grid">${c.checks.map(s=>`<article class="panel"><div class="panel-top"><h3>${esc(s.label)}</h3>${badge(s.status==='READY'?'완료':'준비 필요',s.status==='READY'?'green':'amber')}</div><p>${esc(s.detail)}</p></article>`).join('')}</div>`+
 section('THREE DIFFERENT QUESTIONS','수익률은 세 가지를 나란히 봅니다')+
 `<div class="three-grid"><article class="panel"><h3>비용 후 절대수익</h3><p>전략 자체가 얼마나 벌거나 잃었나? 총수익·CAGR·MDD로 봅니다.</p></article><article class="panel"><h3>전체 동일가중 대비</h3><p>같은 대상 종목을 똑같이 보유하는 것보다 선별이 도움이 됐나? 동일 구간의 전체 적격 종목 gross TR과 비교합니다.</p></article><article class="panel"><h3>시장 TR 대비</h3><p>시장을 보유하는 것보다 나았나? 고정 기준선은 KRX300 TR입니다. KOSPI·KOSDAQ 우량 대형주 중심으로, 전체 종목군과는 다릅니다.</p></article></div><p class="chart-note">전략은 비용 후, 벤치마크는 비용 전 총수익입니다. 월평균 초과수익 × 12는 CAGR 차이나 위험조정 alpha가 아닙니다. 시장 TR 입력은 아직 확보·연결되지 않았습니다.</p>`+
 section('CURRENT DEFINITIONS','현재 승인된 49개와 과거 연구를 분리합니다')+
 `<p class="chart-note">${c.historical_definition_changed}개는 과거 해시와 다르고 ${c.historical_definition_unknown}개는 과거 해시가 없었습니다. 현재 49개 정의는 모두 확인했습니다. 새 정의를 과거에 적용하는 비교이지 당시에도 승인됐다는 뜻은 아닙니다.</p><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="comparison-search" aria-label="현재 버전 팩터 검색" placeholder="한국어 이름 또는 팩터 ID 검색"></label><div id="comparison-factor-results">${comparisonFactors()}</div>`+
 section('PROVENANCE','확인 가능한 범위만 공개합니다')+
 `<section class="panel"><p>DB 확인: ${esc(new Date(c.as_of).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))} KST · 스냅샷이며 자동 동기화되지 않습니다.</p><p>기존 종가 총수익 계약: ${c.return_contracts.map(r=>`${esc(r.source)} ${esc(r.asset_type)} · ${esc(r.field_name)} · ${esc(r.status)} · ${esc(r.coverage_start)} → ${esc(r.coverage_end)}`).join('<br>')}</p><p>이 인증은 시가 체결 총수익이나 시장 TR 입력 인증이 아닙니다.</p><ul>${c.limitations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><div class="download-row"><a class="small-button" href="./data/monthly-comparison.json" download>비교 계획·준비 상태 JSON ↓</a><a class="small-button" href="#factors">과거 정의의 연구 성능 보기 ↗</a></div><p><a class="text-button" href="${esc(c.source_links[0].url)}" target="_blank" rel="noopener noreferrer">${esc(c.source_links[0].label)} ↗</a></p><details class="source"><summary>고정 계획·비용 가정·검증 식별자</summary>${tree({comparison_id:c.comparison_id,registered_at:c.registered_at,plan_sha256:c.plan_sha256,catalog_sha256:c.catalog_sha256,costs:c.costs,independent_oos:c.independent_oos,actual_fill_verified:c.actual_fill_verified})}</details></section>`;
}
document.addEventListener('input',event=>{
 if(event.target.id==='comparison-search'&&comparison)$('#comparison-factor-results').innerHTML=comparisonFactors(event.target.value);
});
